function readResponse(raw) {
  let data = null;
  if (raw.body !== "") {
    try {
      data = JSON.parse(raw.body);
    } catch (err) {
      return { ok: false, status: raw.status, error: "Malformed response body" };
    }
  }
  if (raw.status >= 200 && raw.status < 300) {
    return { ok: true, status: raw.status, data: data };
  }
  const message = data && data.message ? data.message : "HTTP " + raw.status;
  return { ok: false, status: raw.status, error: message };
}

