checkpoint.solution:
function attemptDelays(attempts) {
  const delays = [];
  for (let attempt = 1; attempt < attempts; attempt++) {
    delays.push(Math.min(100 * Math.pow(2, attempt - 1), 800));
  }
  return delays;
}

